draw:function(g,S,v,T){bg(g,'#0b1026','#1e1b4b');stars(g,S,T);var r=this.calc(v),k=C(Math.log(r.D)/Math.log(10)/4.3,.2,1),cw=60+k*170,gy=372,gr=S.hit?C((S.t-S.ht)*2.5,0,1):0;g.fillStyle='#57534e';g.beginPath();g.moveTo(0,gy);if(gr>0){g.lineTo(450-cw*gr-26,gy);g.quadraticCurveTo(450-cw*gr-8,gy-16*gr,450-cw*gr,gy-10*gr);g.quadraticCurveTo(450,gy+cw*.62*gr,450+cw*gr,gy-10*gr);g.quadraticCurveTo(450+cw*gr+8,gy-16*gr,450+cw*gr+26,gy)}g.lineTo(W,gy);g.lineTo(W,H);g.lineTo(0,H);g.closePath();g.fill();g.fillStyle='rgba(0,0,0,.25)';g.fillRect(0,gy+40,W,H);if(S.run&&!S.hit){var u=S.t/.9,an=v.a*PI/180,sx=450-Math.cos(an)*520*(1-u),sy=gy-Math.sin(an)*520*(1-u),rs=5+k*14;g.strokeStyle='rgba(255,180,80,.7)';g.lineWidth=rs;g.lineCap='round';g.beginPath();g.moveTo(sx,sy);g.lineTo(sx-Math.cos(an)*90,sy-Math.sin(an)*90);g.stroke();glow(g,sx,sy,rs*4,[255,220,150],.9);g.fillStyle='#fff7ed';g.beginPath();g.arc(sx,sy,rs,0,7);g.fill()}if(S.hit){var f=C(1-(S.t-S.ht)*1.4,0,1);if(f>0){glow(g,450,gy,260*k+80,[255,240,200],f);g.fillStyle='rgba(255,255,255,'+f*.5+')';g.fillRect(0,0,W,H)}}pd(g,S);if(gr>=1){g.strokeStyle='#fde047';g.lineWidth=2;g.beginPath();g.moveTo(450-cw,gy-34);g.lineTo(450+cw,gy-34);g.stroke();tx(g,'قطر الفوهة ≈ '+(r.D>=1000?fx(r.D/1000,1)+' km':fx(r.D,0)+' m'),450,gy-54,18,'#fde047')}if(!S.run)tx(g,'اختر حجم النيزك وسرعته ثم أسقطه',450,90,19,'#fde68a')},
